-- EconSim MySQL 8.0.16+ schema. Use MySQL/InnoDB migrations.
-- All application UUIDs are CHAR(36), generated by the backend using cryptographic UUIDs.
-- All integer money amounts are smallest units; VNGN demo credits have no cash value.
-- Do not enable Real funding or wagering before legal and provider approval.
CREATE DATABASE IF NOT EXISTS econsim CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE econsim;
SET NAMES utf8mb4;

CREATE TABLE users (
 id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE,
 password_hash VARCHAR(255), display_name VARCHAR(120) NOT NULL,
 country_code CHAR(2) NOT NULL DEFAULT 'NG', region VARCHAR(120),
 status ENUM('pending','active','suspended','closed') NOT NULL DEFAULT 'pending',
 email_verified_at DATETIME(3) NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 CONSTRAINT ck_users_name CHECK(CHAR_LENGTH(display_name) BETWEEN 2 AND 120)
) ENGINE=InnoDB;
-- Normalize email addresses in application code before insert and lookup.
CREATE TABLE auth_sessions (
 id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL,
 token_hash VARBINARY(32) NOT NULL UNIQUE, expires_at DATETIME(3) NOT NULL,
 revoked_at DATETIME(3), device_label VARCHAR(255), ip_address VARCHAR(45),
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 CONSTRAINT fk_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 INDEX idx_sessions_user_expiry(user_id,expires_at)
) ENGINE=InnoDB;
CREATE TABLE auth_one_time_tokens (
 id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL,
 purpose ENUM('verify_email','reset_password') NOT NULL, token_hash VARBINARY(32) NOT NULL UNIQUE,
 expires_at DATETIME(3) NOT NULL, consumed_at DATETIME(3),
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 CONSTRAINT fk_tokens_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 INDEX idx_tokens_user_purpose(user_id,purpose)
) ENGINE=InnoDB;
CREATE TABLE oauth_identities (
 provider VARCHAR(64) NOT NULL, provider_subject VARCHAR(255) NOT NULL,
 user_id CHAR(36) NOT NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY(provider,provider_subject),
 CONSTRAINT fk_oauth_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE user_preferences (
 user_id CHAR(36) PRIMARY KEY, theme ENUM('light','dark','system') NOT NULL DEFAULT 'system',
 preferred_mode ENUM('demo','real') NOT NULL DEFAULT 'demo',
 notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE,
 seen_tours JSON NULL,
 fcm_token TEXT NULL,
 updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE industries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(90) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE user_industries (
 user_id CHAR(36) NOT NULL,industry_id BIGINT UNSIGNED NOT NULL,
 PRIMARY KEY(user_id,industry_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY(industry_id) REFERENCES industries(id)
) ENGINE=InnoDB;
CREATE TABLE external_sources (
 id CHAR(36) PRIMARY KEY,name VARCHAR(200) NOT NULL, origin_url TEXT,
 publisher VARCHAR(200),published_at DATETIME(3),retrieved_at DATETIME(3),raw_sha256 CHAR(64)
) ENGINE=InnoDB;
CREATE TABLE market_events (
 id CHAR(36) PRIMARY KEY,slug VARCHAR(180) NOT NULL UNIQUE,industry_id BIGINT UNSIGNED,
 title VARCHAR(500) NOT NULL,outcome_definition TEXT NOT NULL,resolution_source TEXT NOT NULL,
 resolves_at DATETIME(3) NOT NULL,closes_at DATETIME(3) NOT NULL,
 state ENUM('draft','review','open','suspended','closed','resolved','void') NOT NULL DEFAULT 'draft',
 created_by CHAR(36),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),resolved_at DATETIME(3),
 resolution_outcome BOOLEAN,resolution_notes TEXT,
 FOREIGN KEY(industry_id) REFERENCES industries(id),FOREIGN KEY(created_by) REFERENCES users(id),
 INDEX idx_market_state_close(state,closes_at),
 CONSTRAINT ck_event_closes CHECK(closes_at<=resolves_at),
 CONSTRAINT ck_resolved_outcome CHECK(state<>'resolved' OR resolution_outcome IS NOT NULL)
) ENGINE=InnoDB;
CREATE TABLE study_context_versions (
 id CHAR(36) PRIMARY KEY,event_id CHAR(36) NOT NULL,version INT UNSIGNED NOT NULL,
 summary TEXT NOT NULL, metrics JSON NOT NULL,historical_cases JSON NOT NULL,
 ai_generated BOOLEAN NOT NULL DEFAULT FALSE,editorial_approved_by CHAR(36),
 published_at DATETIME(3),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 UNIQUE KEY uq_context_version(event_id,version),
 FOREIGN KEY(event_id) REFERENCES market_events(id) ON DELETE CASCADE,
 FOREIGN KEY(editorial_approved_by) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE study_context_sources (
 context_id CHAR(36) NOT NULL,source_id CHAR(36) NOT NULL,
 PRIMARY KEY(context_id,source_id),
 FOREIGN KEY(context_id) REFERENCES study_context_versions(id) ON DELETE CASCADE,
 FOREIGN KEY(source_id) REFERENCES external_sources(id)
) ENGINE=InnoDB;
CREATE TABLE forecast_positions (
 id CHAR(36) PRIMARY KEY,event_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,
 mode ENUM('demo','real') NOT NULL DEFAULT 'demo', selected_outcome BOOLEAN NOT NULL,
 stake_minor BIGINT UNSIGNED NOT NULL, quote_probability DECIMAL(7,6) NOT NULL,
 quote_version VARCHAR(100) NOT NULL,
 status ENUM('open','won','lost','void') NOT NULL DEFAULT 'open',
 total_return_minor BIGINT UNSIGNED, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 settled_at DATETIME(3),FOREIGN KEY(event_id) REFERENCES market_events(id),
 FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_positions_user(user_id,mode,created_at),
 CONSTRAINT ck_position_stake CHECK(stake_minor>0),
 CONSTRAINT ck_quote_probability CHECK(quote_probability>0 AND quote_probability<1)
) ENGINE=InnoDB;
CREATE TABLE decision_journal (
 id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,event_id CHAR(36),position_id CHAR(36),
 thesis TEXT NOT NULL,confidence_pct TINYINT UNSIGNED,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY(event_id) REFERENCES market_events(id),
 FOREIGN KEY(position_id) REFERENCES forecast_positions(id),
 CHECK(confidence_pct BETWEEN 0 AND 100 OR confidence_pct IS NULL)
) ENGINE=InnoDB;
CREATE TABLE boardroom_scenarios (
 id CHAR(36) PRIMARY KEY,industry_id BIGINT UNSIGNED,title VARCHAR(300) NOT NULL,
 confidential_body LONGTEXT NOT NULL,reference_case JSON NOT NULL,rubric JSON NOT NULL,
 difficulty ENUM('beginner','intermediate','advanced') NOT NULL DEFAULT 'intermediate',
 approved_by CHAR(36),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(industry_id) REFERENCES industries(id),FOREIGN KEY(approved_by) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE boardroom_challenges (
 id CHAR(36) PRIMARY KEY,host_id CHAR(36) NOT NULL,opponent_id CHAR(36),
 industry_id BIGINT UNSIGNED NOT NULL,scenario_id CHAR(36),
 mode ENUM('demo','real') NOT NULL DEFAULT 'demo',commitment_minor BIGINT UNSIGNED NOT NULL,
 scheduled_at DATETIME(3) NOT NULL,duration_minutes SMALLINT UNSIGNED NOT NULL,
 start_at DATETIME(3),deadline_at DATETIME(3),notified_5min TINYINT(1) DEFAULT 0,notified_started TINYINT(1) DEFAULT 0,
 state ENUM('open','matched','scheduled','live','evaluating','settled','cancelled','forfeited','disputed') NOT NULL DEFAULT 'open',
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(host_id) REFERENCES users(id),FOREIGN KEY(opponent_id) REFERENCES users(id),
 FOREIGN KEY(industry_id) REFERENCES industries(id),FOREIGN KEY(scenario_id) REFERENCES boardroom_scenarios(id),
 INDEX idx_challenges_lobby(state,scheduled_at),
 CHECK(opponent_id IS NULL OR opponent_id<>host_id),CHECK(commitment_minor>0),
 CHECK(duration_minutes BETWEEN 5 AND 120)
) ENGINE=InnoDB;
CREATE TABLE boardroom_participants (
 challenge_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,joined_at DATETIME(3),
 commitment_held_at DATETIME(3),forfeited_at DATETIME(3),
 PRIMARY KEY(challenge_id,user_id),
 FOREIGN KEY(challenge_id) REFERENCES boardroom_challenges(id) ON DELETE CASCADE,
 FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE boardroom_submissions (
 id CHAR(36) PRIMARY KEY,challenge_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,
 answer_text LONGTEXT NOT NULL,submitted_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 UNIQUE KEY uq_challenge_submission(challenge_id,user_id),
 FOREIGN KEY(challenge_id) REFERENCES boardroom_challenges(id),
 FOREIGN KEY(user_id) REFERENCES users(id),
 CHECK(CHAR_LENGTH(answer_text) BETWEEN 40 AND 20000)
) ENGINE=InnoDB;
CREATE TABLE evaluation_runs (
 id CHAR(36) PRIMARY KEY,challenge_id CHAR(36) NOT NULL,model_id VARCHAR(200) NOT NULL,
 rubric_version VARCHAR(80) NOT NULL,rubric_snapshot JSON NOT NULL,
 evaluation_state ENUM('queued','complete','failed','under_review','pending_review') NOT NULL,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),completed_at DATETIME(3),reviewed_by CHAR(36),
 FOREIGN KEY(challenge_id) REFERENCES boardroom_challenges(id),
 FOREIGN KEY(reviewed_by) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE evaluation_scores (
 run_id CHAR(36) NOT NULL,submission_id CHAR(36) NOT NULL,
 financial_mechanics DECIMAL(5,2) NOT NULL,risk_management DECIMAL(5,2) NOT NULL,
 historical_alignment DECIMAL(5,2) NOT NULL,communication DECIMAL(5,2) NOT NULL,
 explanation TEXT NOT NULL,evidence JSON NOT NULL,
 PRIMARY KEY(run_id,submission_id),FOREIGN KEY(run_id) REFERENCES evaluation_runs(id) ON DELETE CASCADE,
 FOREIGN KEY(submission_id) REFERENCES boardroom_submissions(id),
 CHECK(financial_mechanics BETWEEN 0 AND 40),CHECK(risk_management BETWEEN 0 AND 30),
 CHECK(historical_alignment BETWEEN 0 AND 20),CHECK(communication BETWEEN 0 AND 10)
) ENGINE=InnoDB;
-- In production grant INSERT to a dedicated transactional ledger service only.
-- Before posting, it MUST lock affected accounts, verify matching mode/currency,
-- verify zero-sum journal entries and nonnegative user available funds.
-- A regular CHECK cannot enforce cross-row double-entry balancing.
CREATE TABLE ledger_accounts (
 id CHAR(36) PRIMARY KEY,user_id CHAR(36),mode ENUM('demo','real') NOT NULL,
 currency ENUM('VNGN','NGN') NOT NULL,
 kind ENUM('user_available','user_held','platform_issuance','platform_clearing','platform_revenue','payment_clearing') NOT NULL,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id),
 UNIQUE KEY uq_ledger_account(user_id,mode,currency,kind),
 CHECK((mode='demo' AND currency='VNGN') OR (mode='real' AND currency='NGN'))
) ENGINE=InnoDB;
CREATE TABLE ledger_journals (
 id CHAR(36) PRIMARY KEY,idempotency_key VARCHAR(200) NOT NULL UNIQUE,
 mode ENUM('demo','real') NOT NULL,currency ENUM('VNGN','NGN') NOT NULL,
 event_type VARCHAR(100) NOT NULL,reference_id CHAR(36),
 state ENUM('pending','posted','reversed') NOT NULL DEFAULT 'pending',
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),posted_at DATETIME(3),
 CHECK((mode='demo' AND currency='VNGN') OR (mode='real' AND currency='NGN'))
) ENGINE=InnoDB;
CREATE TABLE ledger_entries (
 id CHAR(36) PRIMARY KEY,journal_id CHAR(36) NOT NULL,account_id CHAR(36) NOT NULL,
 amount_minor BIGINT NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(journal_id) REFERENCES ledger_journals(id),
 FOREIGN KEY(account_id) REFERENCES ledger_accounts(id),
 INDEX idx_ledger_account_time(account_id,created_at),CHECK(amount_minor<>0)
) ENGINE=InnoDB;
CREATE TABLE funding_providers (
 id CHAR(36) PRIMARY KEY,slug VARCHAR(80) NOT NULL UNIQUE,display_name VARCHAR(200) NOT NULL,
 status ENUM('disabled','sandbox','enabled') NOT NULL DEFAULT 'disabled'
) ENGINE=InnoDB;
CREATE TABLE funding_intents (
 id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,provider_id CHAR(36) NOT NULL,
 provider_reference VARCHAR(255) UNIQUE,idempotency_key VARCHAR(200) NOT NULL UNIQUE,
 amount_minor BIGINT UNSIGNED NOT NULL,currency ENUM('NGN') NOT NULL DEFAULT 'NGN',
 mode ENUM('real') NOT NULL DEFAULT 'real',
 state ENUM('created','pending','succeeded','failed','expired','refunded') NOT NULL DEFAULT 'created',
 provider_payload JSON NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),confirmed_at DATETIME(3),
 FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(provider_id) REFERENCES funding_providers(id),
 CHECK(amount_minor>0)
) ENGINE=InnoDB;
CREATE TABLE provider_webhook_events (
 id CHAR(36) PRIMARY KEY,provider_id CHAR(36) NOT NULL,
 external_event_id VARCHAR(255) NOT NULL,signature_verified BOOLEAN NOT NULL DEFAULT FALSE,
 received_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),processed_at DATETIME(3),payload_digest CHAR(64),
 UNIQUE KEY uq_provider_webhook(provider_id,external_event_id),
 FOREIGN KEY(provider_id) REFERENCES funding_providers(id)
) ENGINE=InnoDB;
CREATE TABLE learning_scores (
 user_id CHAR(36) PRIMARY KEY,forecast_accuracy DECIMAL(5,2),finance_analysis DECIMAL(5,2),
 risk_identification DECIMAL(5,2),historical_reasoning DECIMAL(5,2),
 executive_communication DECIMAL(5,2),composite DECIMAL(5,2),
 sample_size INT NOT NULL DEFAULT 0,last_calculated_at DATETIME(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 CHECK(composite IS NULL OR composite BETWEEN 0 AND 100)
) ENGINE=InnoDB;
CREATE TABLE badges (
 id CHAR(36) PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,
 title VARCHAR(180) NOT NULL,requirement JSON NOT NULL
) ENGINE=InnoDB;
CREATE TABLE user_badges (
 user_id CHAR(36) NOT NULL,badge_id CHAR(36) NOT NULL,
 awarded_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,badge_id),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY(badge_id) REFERENCES badges(id)
) ENGINE=InnoDB;
CREATE TABLE xp_events (
 id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,xp INT UNSIGNED NOT NULL,
 reason VARCHAR(250) NOT NULL,source_key VARCHAR(200) NOT NULL UNIQUE,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id),CHECK(xp>0)
) ENGINE=InnoDB;
CREATE TABLE scenario_lab_runs (
 id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,model_version VARCHAR(80) NOT NULL,
 parameters JSON NOT NULL,results JSON NOT NULL,limitations TEXT NOT NULL,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE mentor_conversations (
 id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE mentor_messages (
 id CHAR(36) PRIMARY KEY,conversation_id CHAR(36) NOT NULL,
 role ENUM('user','assistant') NOT NULL,content LONGTEXT NOT NULL,source_citations JSON NOT NULL,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(conversation_id) REFERENCES mentor_conversations(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE platform_features (
 code VARCHAR(100) PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT FALSE,
 updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB;
CREATE TABLE platform_settings (
 `key` VARCHAR(100) PRIMARY KEY,
 `value` TEXT NOT NULL,
 `updated_at` DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB;
CREATE TABLE ai_grading_corrections (
 id CHAR(36) PRIMARY KEY,
 run_id CHAR(36) NOT NULL,
 challenge_id CHAR(36) NOT NULL,
 submission_id CHAR(36) NOT NULL,
 admin_id CHAR(36),
 original_ai_scores JSON NOT NULL,
 admin_scores JSON NOT NULL,
 ai_explanation TEXT,
 admin_explanation TEXT,
 correction_notes TEXT,
 action_taken ENUM('approved_ai', 'corrected', 'admin_override', 'rejected_zero') NOT NULL,
 created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB;
CREATE TABLE user_notifications (
 id VARCHAR(64) PRIMARY KEY,
 user_id CHAR(36) NOT NULL,
 title VARCHAR(191) NOT NULL,
 message TEXT NOT NULL,
 target_page VARCHAR(64) NOT NULL DEFAULT 'dashboard',
 target_id VARCHAR(64) NULL,
 category VARCHAR(64) NOT NULL DEFAULT 'boardroom',
 is_read TINYINT(1) NOT NULL DEFAULT 0,
 created_at DATETIME(3) NOT NULL,
 INDEX idx_user_read (user_id, is_read, created_at),
 CONSTRAINT fk_user_notifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
